import { verbosity, restoreVerbosity, getVerbosity, log, verb, debug } from '../src/cliLog';

let verbosityBefore: ReturnType<typeof getVerbosity>;

beforeEach(() => {
    do {} while (restoreVerbosity()); // pop back to root state
});

afterEach(() => {
    do {} while (restoreVerbosity()); // pop back to root state
});

test('verbosity sets and restores correctly', () => {
    verbosityBefore = getVerbosity();
    expect(verbosityBefore).toEqual({ quiet: false, verbose: false, debug: false });

    verbosity({ quiet: true });
    expect(getVerbosity()).toEqual({ quiet: true, verbose: false, debug: false });

    verbosity({ verbose: true });
    expect(getVerbosity()).toEqual({ quiet: false, verbose: true, debug: false });

    expect(restoreVerbosity()).toBe(true);
    expect(getVerbosity()).toEqual({ quiet: true, verbose: false, debug: false });

    expect(restoreVerbosity()).toBe(true);
    expect(getVerbosity()).toEqual({ quiet: false, verbose: false, debug: false });

});